{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated-run testing is undocumented."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring define a narrow grid-puzzle comparison. The reported score describes one run; repeated-run consistency and broader coverage are not established."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated runs, the findings establish neither stability nor instability."
        }
      ],
      "instrument_review": "Exact-grid scoring supports interpreting the single observed result. The documented absence of repetition leaves score consistency untested for the intended comparison."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations held the stated conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Controlled repetition supports consistency under the stated conditions and definition. This finding remains limited to the tested system, puzzles, and conditions; it does not establish broader performance."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage documents repeated testing under matching conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated testing documents substantial inconsistency under unchanged conditions. The single 70% result therefore cannot adequately characterize repeated performance; comparisons should report the observed variability."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation supplies no evidence of score consistency."
        }
      ],
      "instrument_review": "Installation guidance documents setup, but does not establish successful replication or stable scores. The evidence remains a single reported result for the narrow grid-puzzle use."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher observed result on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison of intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison matches the intended grid-puzzle use. Fixed instructions and exact-grid scoring specify parts of the comparison, but repeated-run consistency and other resource controls are undocumented. Interpretation should remain limited to the evaluated conditions."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on these puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply the missing cross-domain evidence."
        }
      ],
      "instrument_review": "The intended selection use exceeds the supplied task coverage. Scoring supports the narrow observed comparison, but general-intelligence selection lacks supporting findings across domains; consistency and complete comparison controls are also undocumented."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "No initial evidence connects those scores to improved real workshop decisions with A versus B."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied setting, with a reported difference interval of 12 to 28 percentage points."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness findings alone do not establish a workplace safety improvement."
        }
      ],
      "instrument_review": "The later preregistered randomized comparison, blinded correctness checks, new cases, and reported uncertainty support choosing A for correctness in this workshop under the studied conditions. They do not establish the initial test scores' predictive accuracy, benefits in other workshops, or effects on time and safety."
    }
  ],
  "closing_note": "No material instruction ambiguity was identified. Labels distinguish explicit conflict from missing evidence; no aggregate quality score was calculated."
}
